validator:
function validate(input) {
  const [{ Actions = [] }] = input;
  const kinds = ['view', 'like', 'reaction', 'comment', 'report', 'share'];
  for (const [user, post, date, action, extra] of Actions) {
    if (user === null || post === null || date === null || action === null) return 'user_id, post_id, action_date and action are required.';
    if (!kinds.includes(action)) return `Unknown action ${action}.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `action_date ${date} is not YYYY-MM-DD.`;
    if (action === 'report' && extra === null) return 'A report needs a reason in extra.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const kinds = ['view', 'like', 'reaction', 'comment', 'report', 'report', 'report', 'share'];
  const reasons = ['spam', 'racism', 'violence'];
  const moods = ['love', 'wow', null];
  const small = size === 'small';
  const dates = small ? ['2019-07-03', '2019-07-04', '2019-07-04', '2019-07-05'] : ['2019-07-01', '2019-07-02', '2019-07-03', '2019-07-04', '2019-07-04', '2019-07-05'];
  const users = small ? 4 : 300, posts = small ? 4 : 400, rows = small ? pick(9) : 2000;
  const Actions = [];
  for (let i = 0; i < rows; i++) {
    if (Actions.length && rand() < 0.15) { Actions.push([...Actions[pick(Actions.length)]]); continue; }
    const action = kinds[pick(kinds.length)];
    const extra = action === 'report' ? reasons[pick(reasons.length)] : action === 'reaction' ? moods[pick(moods.length)] : null;
    Actions.push([1 + pick(users), 1 + pick(posts), dates[pick(dates.length)], action, extra]);
  }
  return [{ Actions }];
}
